WITH base AS (SELECT *, CONCAT(promo_code, ' ', channel) AS promo_code_channel, COALESCE(channel, 'OTHER') AS channel_filled FROM promotions WHERE channel IS NOT NULL AND ends_on > '2023-06-01'), deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY channel ORDER BY discount_pct DESC, id ASC) AS rn FROM base QUALIFY rn = 1), attributed AS (SELECT a.*, pr.id AS promo_id, pr.promo_code AS promotion_promo_code, pr.discount_pct AS promotion_discount_pct FROM deduped a JOIN promotions pr ON a.channel <=> pr.channel AND a.starts_on BETWEEN pr.starts_on AND pr.ends_on), with_windows AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY channel, promo_code ORDER BY promo_id DESC, id ASC, promo_id ASC) AS row_seq, ROUND(discount_pct / SUM(discount_pct) OVER (PARTITION BY promotion_promo_code), 4) AS discount_pct_share FROM attributed) SELECT DATE_TRUNC('YEAR', starts_on) AS year_start, CASE WHEN row_seq >= 8 THEN 'LARGE' ELSE 'SMALL' END AS row_seq_tier, MAX(promo_id) AS max_promo_id, APPROX_PERCENTILE(promo_id, ARRAY(0.25, 0.5, 0.75)) AS promo_id_quartiles, COUNT(DISTINCT promo_code) AS distinct_promo_codes FROM with_windows GROUP BY year_start, row_seq_tier ORDER BY distinct_promo_codes DESC;
